(question_code,track,level,topic,prompt,choices,correct_index,explanation,active,question_type,learning_objective,formula,tags)
values
('MET-M-B-103','math','basic','تحويل سرعة الرياح','تبلغ سرعة الرياح 10 m/s. ما سرعتها بالكيلومتر في الساعة؟',
'["18 km/h","24 km/h","36 km/h","60 km/h"]'::jsonb,2,
'للتحويل من متر/ثانية إلى كيلومتر/ساعة نضرب في 3.6؛ إذن 10 × 3.6 = 36 km/h.','true','calculation','تحويل وحدات سرعة الرياح','km/h = m/s × 3.6',array['رياح','وحدات']),
('MET-M-B-104','math','basic','تراكم الهطول','إذا سُجل هطول بمعدل ثابت 4 mm/h لمدة 3 ساعات، فما كمية الهطول الكلية؟',
'["7 mm","12 mm","16 mm","24 mm"]'::jsonb,1,
'عند ثبات المعدل، التراكم يساوي المعدل مضروباً في الزمن: 4 × 3 = 12 mm.','true','calculation','حساب تراكم الهطول من المعدل والزمن','P = R × t',array['هطول','تراكم']),
('MET-M-B-105','math','basic','متوسط درجة الحرارة','كانت درجات الحرارة في أربع قراءات متساوية الفاصل 10 و12 و14 و16 °C. ما المتوسط الحسابي لهذه القراءات؟',
'["12 °C","13 °C","14 °C","15 °C"]'::jsonb,1,
'نجمع القراءات ثم نقسم على عددها: (10+12+14+16)/4 = 13 °C.','true','calculation','حساب المتوسط الحسابي لقراءات الرصد','Tmean = ΣT / n',array['حرارة','إحصاء']),
('MET-M-B-106','math','basic','تحويل فهرنهايت إلى سلسيوس','ما درجة الحرارة المكافئة لـ 68 °F على مقياس سلسيوس؟',
'["10 °C","15 °C","20 °C","25 °C"]'::jsonb,2,
'نستخدم العلاقة C = (F−32)×5/9؛ وعند 68°F تكون النتيجة 20°C.','true','calculation','التحويل بين فهرنهايت وسلسيوس','°C = (°F − 32) × 5/9',array['حرارة','تحويل وحدات']),
('MET-M-I-103','math','intermediate','تدرج الضغط الأفقي','انخفض الضغط بمقدار 6 hPa عبر مسافة 300 km. ما مقدار التغير لكل 100 km؟',
'["0.5 hPa/100 km","1 hPa/100 km","2 hPa/100 km","3 hPa/100 km"]'::jsonb,2,
'نقسم مقدار التغير 6 hPa على 3 فترات، كل منها 100 km، فيكون 2 hPa لكل 100 km.','true','calculation','تقدير تدرج الضغط الأفقي','6 / (300/100) = 2 hPa/100 km',array['ضغط','تدرج أفقي']),
('MET-M-I-104','math','intermediate','تقدير قاعدة السحب','في تقدير تقريبي لقاعدة السحب الركامية، إذا كان الفرق بين الحرارة ونقطة الندى 8 °C، فما ارتفاع القاعدة التقريبي؟',
'["250 m","500 m","1000 m","2000 m"]'::jsonb,2,
'قاعدة تقريبية شائعة: نحو 125 متراً لكل درجة مئوية من فرق الحرارة ونقطة الندى؛ 8 × 125 ≈ 1000 متر. هذه قاعدة تقديرية وليست بديلاً عن القياس.','true','calculation','تقدير ارتفاع قاعدة السحب من فرق الحرارة ونقطة الندى','Cloud base ≈ 125 × (T−Td) m',array['سحب','نقطة الندى']),
('MET-M-I-105','math','intermediate','تحويل سرعة الرياح','ما سرعة الرياح المكافئة لـ 18 km/h بوحدة m/s تقريباً؟',
'["3 m/s","5 m/s","6.5 m/s","10 m/s"]'::jsonb,1,
'نقسم km/h على 3.6: 18/3.6 = 5 m/s.','true','calculation','تحويل سرعة الرياح إلى النظام الدولي','m/s = km/h / 3.6',array['رياح','تحويل وحدات']),
('MET-M-A-103','math','advanced','شذوذ درجة الحرارة','بلغت الحرارة المرصودة 26 °C بينما كان المتوسط المناخي للفترة نفسها 22 °C. ما شذوذ الحرارة؟',
'["+4 °C","−4 °C","+48 °C","0 °C"]'::jsonb,0,
